effect.shader:
const int AMOSTRAS = 16;
const float TAU = 6.2831853;

/** Luminância ITU-R BT.709. */
float luma(vec3 c) {
    return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

/** Só o que está acima do limiar da luz, com transição suave. */
float apenasAsLuzes(vec3 c) {
    float l = luma(c);
    return smoothstep(threshold, threshold + max(softness, 1e-4), l);
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    vec2 tam = vec2(textureSize(inputImg, 0));
    vec2 passo = radius / tam;

    // Borrão radial do recorte das luzes: 16 amostras num círculo.
    float acumulado = apenasAsLuzes(original.rgb) * 0.5;
    float peso = 0.5;
    for (int i = 0; i < AMOSTRAS; i++) {
        float ang = TAU * (float(i) + 0.5) / float(AMOSTRAS);
        vec2 d = vec2(cos(ang), sin(ang)) * passo;
        vec3 cor = texture(inputImg, acScreenNorm + d).rgb;
        acumulado += apenasAsLuzes(cor);
        peso += 1.0;
    }
    float brilhoBorrado = acumulado / peso;

    vec3 halo = haloColor.rgb * brilhoBorrado * intensity * haloColor.a;

    // Screen: luz nunca apaga luz.
    vec3 cor = 1.0 - (1.0 - original.rgb) * (1.0 - halo);

    fragColor = vec4(cor, original.a);
}
